## ----echo=FALSE---------------------------------------------------------------
  set.seed(seed)


## ----echo=TRUE----------------------------------------------------------------
mdl_norm <- list(n     = 500, 
                 q     = 2,
                 mu    = c(5, -2),
                 sigma = rbind(c(5.0, 1.5),
                               c(1.5, 1.0)))
simu_norm <- simuNorm(mdl_norm)

mdl_ar <- list(n     = 500, 
               mu    = 5,
               sigma = 1,
               phi   = c(0.75))
simu_ar <- simuAR(mdl_ar)

mdl_var <- list(n     = 500, 
                p     = 1,
                q     = 2,
                mu    = c(5, -2),
                sigma = rbind(c(5.0, 1.5),
                              c(1.5, 1.0)),
                phi   = rbind(c(0.50, 0.30),
                              c(0.20, 0.70)))
simu_var <- simuVAR(mdl_var)

mdl_hmm <- list(n     = 500, 
                q     = 2,
                mu    = rbind(c(5, -2),
                              c(10, 2)),
                sigma = list(rbind(c(5.0, 1.5),
                                   c(1.5, 1.0)),
                             rbind(c(7.0, 3.0),
                                   c(3.0, 2.0))),
                k     = 2,
                P     = rbind(c(0.95, 0.10),
                              c(0.05, 0.90)))
simu_hmm <- simuHMM(mdl_hmm)

mdl_ms <- list(n     = 500, 
               mu    = c(5,10),
               sigma = c(1,1),
               phi   = c(0.75),
               k     = 2,
               P     = rbind(c(0.95, 0.10),
                             c(0.05, 0.90)))
simu_msar <- simuMSAR(mdl_ms)

mdl_msvar <- list(n     = 500, 
                  p     = 1,
                  q     = 2,
                  mu    = rbind(c(5, -2),
                                c(10, 2)),
                  sigma = list(rbind(c(5.0, 1.5),
                                     c(1.5, 1.0)),
                               rbind(c(7.0, 3.0),
                                     c(3.0, 2.0))),
                  phi   = rbind(c(0.50, 0.30),
                                c(0.20, 0.70)),
                  k     = 2,
                  P     = rbind(c(0.95, 0.10),
                                c(0.05, 0.90)))
simu_msvar <- simuMSVAR(mdl_msvar)


## ----sims, fig.align='center', fig.width=6, fig.height=4.2, out.width=if (knitr::is_latex_output()) '\\textwidth' else NULL, out.extra='', fig.cap = "Simulated linear (left column) and Markov switching (right column) processes. Abrupt shifts between regimes are visible in the Markov switching processes.", fig.alt = "A three-by-two grid of simulated time series line plots. The left column shows the linear processes (multivariate normal, autoregressive, and vector autoregressive) and the right column shows the corresponding Markov switching processes (hidden Markov, Markov switching autoregressive, and Markov switching vector autoregressive), in which abrupt shifts between regimes are visible."----
# bottom row made taller so all panels share the same plot height (it holds the shared x-axis)
d <- 2 * 0.66 * par("csi") / par("din")[2]; a <- (1 - d) / 3  # 0.66 = R's margin shrink for 3-row layouts (see ?par)
layout(matrix(1:6, 3, 2, byrow = TRUE), heights = c(a, a, a + d))
par(mar=c(0.5, 4, 1.8, 1))
matplot(simu_norm$y, type = "l", xlab = "", ylab = "", main = "Multivariate normal process",cex.main=1, col = c("black", "blue"), xaxt = "n")
matplot(simu_hmm$y, type = "l", xlab = "", ylab = "", main = "Hidden Markov process",cex.main=1, col = c("black", "blue"), xaxt = "n")
plot(simu_ar$y, type = "l", xlab = "", ylab = "", main = "Autoregressive process",cex.main=1, xaxt = "n")
plot(simu_msar$y, type = "l", xlab = "", ylab = "", main = "Markov switching autoregressive process",cex.main=1, xaxt = "n")
par(mar=c(2.5, 4, 1.8, 1))
matplot(simu_var$y, type = "l", xlab = "", ylab = "", main = "Vector autoregressive process",cex.main=1, col = c("black", "blue"))
matplot(simu_msvar$y, type = "l", xlab = "", ylab = "", main = "Markov switching vector autoregressive process",cex.main=1, col = c("black", "blue"))


